from AlgorithmImports import *


class ExactStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_closes = []
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.pending_orders = {}

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(float(data.Bars[self.spy].Close))
            if len(self.spy_closes) > 101:
                self.spy_closes.pop(0)

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        self._evaluate_sells(data)
        self._evaluate_buys(data)

    def _evaluate_sells(self, data):
        if (
            self.strategy_a_lot > 0
            and not self._has_pending_order("A", "sell")
            and len(self.spy_closes) >= 101
            and self._spy_crosses_below_sma()
        ):
            self._submit_order("A", "sell", self.spy, -self.strategy_a_lot)

        if (
            self.strategy_b_lot > 0
            and not self._has_pending_order("B", "sell")
            and self.rsi.IsReady
            and self.rsi.Current.Value > 60
        ):
            self._submit_order("B", "sell", self.aapl, -self.strategy_b_lot)

    def _evaluate_buys(self, data):
        if (
            self.strategy_a_lot == 0
            and not self._has_pending_order("A", "buy")
            and len(self.spy_closes) >= 101
            and self._spy_crosses_above_sma()
        ):
            close = float(data.Bars[self.spy].Close)
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / close)

            if quantity > 0:
                self._submit_order("A", "buy", self.spy, quantity)

        if (
            self.strategy_b_lot == 0
            and not self._has_pending_order("B", "buy")
            and self.aapl_red_streak >= 3
        ):
            close = float(data.Bars[self.aapl].Close)

            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(20000 / close)

                if quantity > 0:
                    self._submit_order("B", "buy", self.aapl, quantity)

    def _spy_crosses_above_sma(self):
        today_close = self.spy_closes[-1]
        yesterday_close = self.spy_closes[-2]

        today_sma = sum(self.spy_closes[-100:]) / 100.0
        yesterday_sma = sum(self.spy_closes[-101:-1]) / 100.0

        return (
            yesterday_close <= yesterday_sma
            and today_close > today_sma
        )

    def _spy_crosses_below_sma(self):
        today_close = self.spy_closes[-1]
        yesterday_close = self.spy_closes[-2]

        today_sma = sum(self.spy_closes[-100:]) / 100.0
        yesterday_sma = sum(self.spy_closes[-101:-1]) / 100.0

        return (
            yesterday_close >= yesterday_sma
            and today_close < today_sma
        )

    def _submit_order(self, strategy, side, symbol, quantity):
        ticket = self.MarketOrder(
            symbol,
            quantity,
            tag="Strategy {} {}".format(strategy, side)
        )

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = (strategy, side)

    def _has_pending_order(self, strategy, side):
        return any(
            order_strategy == strategy and order_side == side
            for order_strategy, order_side in self.pending_orders.values()
        )

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        strategy, side = self.pending_orders[order_id]
        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if strategy == "A":
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
            else:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        ):
            del self.pending_orders[order_id]
