        if self.lots["A"] == 0 and spy_crosses_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            shares = floor(target_value / spy_close)

            if shares > 0:
                self._buy_lot("A", self.spy, shares, "Strategy A buy")

        if self.lots["B"] == 0 and aapl_has_three_red_days:
            if float(self.Portfolio.Cash) >= 20000:
                shares = floor(20000 / float(data.Bars[self.aapl].Close))

                if shares > 0:
                    self._buy_lot("B", self.aapl, shares, "Strategy B buy")

