            spy_close = float(data.Bars[self.spy].Close)

            if self.spy_sma.IsReady:
                self.spy_previous_sma = float(self.spy_sma.Current.Value)

            self.spy_previous_close = spy_close

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

    def _buy_lot(self, slot, symbol, shares, tag):
        ticket = self.MarketOrder(symbol, shares, False, tag)
        filled = int(ticket.QuantityFilled)

        if filled > 0:
            self.lots[slot] += filled

    def _sell_lot(self, slot, symbol, tag):
        shares = self.lots[slot]

        if shares <= 0:
            return

        ticket = self.MarketOrder(symbol, -shares, False, tag)
        filled = abs(int(ticket.QuantityFilled))

        self.lots[slot] = max(0, self.lots[slot] - filled)
