from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        current_spy_close = None
        current_aapl_close = None

        if self.spy in data.Bars:
            current_spy_close = float(data.Bars[self.spy].Close)
            self.previous_spy_close = current_spy_close

            if self.spy_sma.IsReady:
                self.previous_spy_sma = float(self.spy_sma.Current.Value)

        if self.aapl in data.Bars:
            current_aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = current_aapl_close

        if self.IsWarmingUp:
            return

        required_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        if any(symbol not in data.Bars for symbol in required_symbols):
            return

        if current_spy_close is None or current_aapl_close is None:
            return

        if not self.spy_sma.IsReady or previous_spy_close is None or previous_spy_sma is None:
            spy_cross_above = False
            spy_cross_below = False
        else:
            current_spy_sma = float(self.spy_sma.Current.Value)

            spy_cross_above = (
                previous_spy_close <= previous_spy_sma
                and current_spy_close > current_spy_sma
            )

            spy_cross_below = (
                previous_spy_close >= previous_spy_sma
                and current_spy_close < current_spy_sma
            )

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
        )

        # Evaluate sells before buys.
        spy_lot = int(self.Portfolio[self.spy].Quantity)
        if (
            spy_lot > 0
            and spy_cross_below
            and not self._has_pending_order("A")
        ):
            self._submit_order("A", self.spy, -spy_lot, "Strategy A Sell")

        aapl_lot = int(self.Portfolio[self.aapl].Quantity)
        if (
            aapl_lot > 0
            and aapl_rsi_above_60
            and not self._has_pending_order("B")
        ):
            self._submit_order("B", self.aapl, -aapl_lot, "Strategy B Sell")

        # Slot 1: Strategy A buy.
        spy_lot = int(self.Portfolio[self.spy].Quantity)
        if (
            spy_lot == 0
            and spy_cross_above
            and not self._has_pending_order("A")
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            shares = int(target_value / current_spy_close)

            if shares > 0:
                self._submit_order("A", self.spy, shares, "Strategy A Buy")

        # Slot 2: Strategy B buy.
        aapl_lot = int(self.Portfolio[self.aapl].Quantity)
        if (
            aapl_lot == 0
            and self.aapl_red_streak >= 3
            and not self._has_pending_order("B")
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            shares = int(20000.0 / current_aapl_close)

            if shares > 0:
                self._submit_order("B", self.aapl, shares, "Strategy B Buy")

    def _submit_order(self, strategy, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        if ticket is not None:
            self.pending_orders[ticket.OrderId] = strategy

    def _has_pending_order(self, strategy):
        return strategy in self.pending_orders.values()

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.pop(orderEvent.OrderId, None)
